mapper.select:

where d.del_flag = 0

    and d.event_id = #{eventId}


    and d.subscription_id = #{subscriptionId}


    and d.delivery_status = #{deliveryStatus}


    and d.create_time >= #{startTime}


    and d.create_time < #{endTime}

order by d.create_time desc, d.id desc


where d.event_id = #{eventId}
  and d.event_message_id = #{eventMessageId}
  and d.del_flag = 0
order by d.id
